ruleBookInfo.coverUrl:
@js:(function () {
  var h = String(result);
  var m = h.match(/<meta[^>]+property="og:image"[^>]*content="([^"]*)"/i);
  if (!m) { m = h.match(/<meta[^>]+content="([^"]*)"[^>]*property="og:image"/i); }
  if (!m) { return ''; }
  var u = m[1];
  if (u.indexOf('http') !== 0) {
    var host = 'http://www.xbiquge.bz';
    var hm = String(bookUrl).match(/^https?:\/\/[^\/]+/);
    if (hm) { host = hm[0]; }
    if (u.substring(0, 1) !== '/') { u = '/' + u; }
    u = host + u;
  }
  return u;
})()

ruleContent.content:
@js:(function () {
  var h = String(result);
  var re = /qsbs\.bb\('([^']*)'\)/g;
  var out = '';
  var m;
  while ((m = re.exec(h)) !== null) {
    try { out += java.base64Decode(m[1]); } catch (e) { }
  }
  return out;
})()

ruleContent.nextContentUrl:
@js:(function () {
  var h = String(result);
  var host = '';
  var hm = String(baseUrl).match(/^https?:\/\/[^\/]+/);
  if (hm) { host = hm[0]; }
  var nb = h.match(/<a href="([^"]+)">\u4e0b\u4e00\u7ae0<\/a>/);
  if (!nb) { return ''; }
  var nx = nb[1];
  var cur = String(baseUrl).replace(/^.*\//, '').replace(/\.html.*$/, '');
  var nf = nx.replace(/^.*\//, '').replace(/\.html.*$/, '');
  var ida = cur.replace(/_\d+$/, '');
  var idb = nf.replace(/_\d+$/, '');
  if (ida === idb) {
    if (nx.indexOf('http') !== 0 && nx.substring(0, 1) === '/') { nx = host + nx; }
    return nx;
  }
  return '';
})()

ruleToc.chapterList:
@js:(function () {
  var h = String(result);
  var sm = h.match(/<select[^>]*>([\s\S]*?)<\/select>/);
  if (sm) {
    var oc = sm[1].match(/<option/g);
    var n0 = oc ? oc.length : 0;
    if (n0 < 2) { return []; }
  }
  var doc = org.jsoup.Jsoup.parse(h);
  var uls = doc.select('ul.section-list');
  var best = null, bestN = -1, ycx = null;
  for (var i = 0; i < uls.size(); i++) {
    var u = uls.get(i);
    var n = u.select('li').size();
    if (u.hasClass('ycxsid')) { ycx = u; }
    if (n >= bestN) { bestN = n; best = u; }
  }
  var ul = (ycx !== null) ? ycx : best;
  if (ul === null) { return []; }
  var lis = ul.select('li');
  var N = lis.size();
  var K1 = 0, K2 = 0;
  if (ycx !== null) {
    var st = h.match(/<style>[\s\S]*?ycxsid[\s\S]*?<\/style>/);
    var seg = st ? st[0] : '';
    var m1 = seg.match(/nth-child\(\d+\)/g);
    var m2 = seg.match(/nth-last-child\(\d+\)/g);
    K1 = m1 ? m1.length : 0;
    K2 = m2 ? m2.length : 0;
  }
  var lo = K1, hi = N - K2;
  if (lo >= hi) { lo = 0; hi = N; }
  var src = String(baseUrl);
  if (src.indexOf('http') !== 0) { src = String(bookUrl); }
  var host = '';
  var hm = src.match(/^https?:\/\/[^\/]+/);
  if (hm) { host = hm[0]; }
  var arr = [];
  for (var j = lo; j < hi; j++) {
    var al = lis.get(j).select('a').first();
    if (al === null) { continue; }
    var href = String(al.attr('href'));
    if (href.indexOf('http') !== 0 && href.substring(0, 1) === '/') { href = host + href; }
    arr.push({ name: String(al.text()), url: href });
  }
  return arr;
})()

ruleToc.nextTocUrl:
@js:(function () {
  var h = String(result);
  var host = '';
  var hm = String(baseUrl).match(/^https?:\/\/[^\/]+/);
  if (hm) { host = hm[0]; }
  var sm = h.match(/<select[^>]*>([\s\S]*?)<\/select>/);
  if (sm) {
    var opts = sm[1].match(/<option[^>]*>/g);
    if (opts) {
      var cur = -1;
      for (var i = 0; i < opts.length; i++) {
        if (opts[i].indexOf('selected') >= 0) { cur = i; }
      }
      if (cur >= 0 && cur + 1 < opts.length) {
        var vm = opts[cur + 1].match(/value="([^"]+)"/);
        if (vm) {
          var nx = vm[1];
          if (nx.indexOf('http') !== 0 && nx.substring(0, 1) === '/') { nx = host + nx; }
          return nx;
        }
      }
    }
    return '';
  }
  var doc = org.jsoup.Jsoup.parse(h);
  var uls = doc.select('ul.section-list');
  var maxN = 0;
  for (var k = 0; k < uls.size(); k++) {
    var n = uls.get(k).select('li').size();
    if (n > maxN) { maxN = n; }
  }
  if (maxN < 100) { return ''; }
  var bm = h.match(/<a href="([^"]+)" class="btn-mulu"/);
  if (bm) {
    var u = bm[1];
    if (u.indexOf('http') !== 0 && u.substring(0, 1) === '/') { u = host + u; }
    return u;
  }
  return '';
})()
